-- SocialAmbak — initial schema (MySQL 8.0.16+ / 8.4 LTS, InnoDB, utf8mb4)
--
-- Conventions
--   * Primary keys are BINARY(16) UUIDv7 generated by the app: time-ordered, so inserts append to the
--     clustered index instead of splitting random pages, and safe to expose in URLs.
--   * All DATETIME(3) values are UTC (the app sets time_zone = '+00:00' on every connection).
--   * utf8mb4_0900_ai_ci makes usernames and emails case-insensitive for uniqueness and lookup.
--   * MySQL forbids CHECK constraints on columns used by cascading foreign keys, so rules such as
--     "you can't follow yourself" are enforced in the service layer instead.
--   * Soft deletes via deleted_at; counters denormalised on hot rows and updated in the same transaction.

SET NAMES utf8mb4;

-- ---------- identity ----------
CREATE TABLE users (
  id                  BINARY(16)   NOT NULL,
  username            VARCHAR(30)  NOT NULL,
  full_name           VARCHAR(60)  NOT NULL,
  email               VARCHAR(254) NOT NULL,
  email_verified_at   DATETIME(3)  NULL,
  -- Phone is never stored in plain text:
  --   phone_ciphertext = AES-256-GCM (iv | tag | ciphertext), associated data bound to the user id
  --   phone_hash       = HMAC-SHA256 blind index for uniqueness and sign-in lookup
  phone_ciphertext    VARBINARY(128) NOT NULL,
  phone_hash          BINARY(32)   NOT NULL,
  phone_key_version   SMALLINT UNSIGNED NOT NULL DEFAULT 1,
  phone_verified_at   DATETIME(3)  NULL,
  password_hash       VARCHAR(255) NOT NULL,          -- argon2id, PHC string format
  password_changed_at DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  date_of_birth       DATE         NOT NULL,
  bio                 VARCHAR(150) NOT NULL DEFAULT '',
  website             VARCHAR(200) NULL,
  avatar_key          VARCHAR(300) NULL,
  is_private          BOOLEAN      NOT NULL DEFAULT FALSE,
  status              ENUM('pending_verification','active','deactivated','suspended') NOT NULL DEFAULT 'pending_verification',
  role                ENUM('user','moderator','admin') NOT NULL DEFAULT 'user',
  followers_count     INT UNSIGNED NOT NULL DEFAULT 0,
  following_count     INT UNSIGNED NOT NULL DEFAULT 0,
  posts_count         INT UNSIGNED NOT NULL DEFAULT 0,
  last_login_at       DATETIME(3)  NULL,
  created_at          DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at          DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  deleted_at          DATETIME(3)  NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_users_username (username),
  UNIQUE KEY uq_users_email (email),
  UNIQUE KEY uq_users_phone_hash (phone_hash),
  KEY idx_users_status_created (status, created_at),
  FULLTEXT KEY ft_users_search (username, full_name) WITH PARSER ngram,
  CONSTRAINT chk_users_username CHECK (REGEXP_LIKE(username, '^[a-z0-9._]{3,30}$', 'c'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE user_settings (
  user_id               BINARY(16) NOT NULL,
  theme                 ENUM('system','light','dark') NOT NULL DEFAULT 'system',
  messages_from         ENUM('everyone','following','nobody') NOT NULL DEFAULT 'everyone',
  mentions_from         ENUM('everyone','following','nobody') NOT NULL DEFAULT 'everyone',
  show_activity_status  BOOLEAN NOT NULL DEFAULT TRUE,
  notify_likes          BOOLEAN NOT NULL DEFAULT TRUE,
  notify_comments       BOOLEAN NOT NULL DEFAULT TRUE,
  notify_follows        BOOLEAN NOT NULL DEFAULT TRUE,
  notify_messages       BOOLEAN NOT NULL DEFAULT TRUE,
  updated_at            DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (user_id),
  CONSTRAINT fk_settings_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Refresh-token sessions. Only a SHA-256 hash of the token is stored.
-- family_id groups rotated tokens so reuse of an old token revokes the whole chain.
CREATE TABLE sessions (
  id                  BINARY(16)   NOT NULL,
  user_id             BINARY(16)   NOT NULL,
  family_id           BINARY(16)   NOT NULL,
  refresh_token_hash  BINARY(32)   NOT NULL,
  user_agent          VARCHAR(300) NULL,
  ip                  VARCHAR(45)  NULL,
  created_at          DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  last_used_at        DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  expires_at          DATETIME(3)  NOT NULL,
  revoked_at          DATETIME(3)  NULL,
  replaced_by         BINARY(16)   NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_sessions_token (refresh_token_hash),
  KEY idx_sessions_user (user_id, revoked_at),
  KEY idx_sessions_family (family_id),
  KEY idx_sessions_expires (expires_at),
  CONSTRAINT fk_sessions_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- One-time codes for email/phone verification. Only an HMAC of the code is stored.
CREATE TABLE verification_codes (
  id            BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  user_id       BINARY(16) NOT NULL,
  channel       ENUM('email','phone') NOT NULL,
  purpose       ENUM('signup','login','password_reset','change_contact') NOT NULL,
  code_hash     BINARY(32) NOT NULL,
  attempts      TINYINT UNSIGNED NOT NULL DEFAULT 0,
  max_attempts  TINYINT UNSIGNED NOT NULL DEFAULT 5,
  expires_at    DATETIME(3) NOT NULL,
  consumed_at   DATETIME(3) NULL,
  created_at    DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY idx_codes_lookup (user_id, channel, purpose, created_at),
  KEY idx_codes_created (created_at),
  CONSTRAINT fk_codes_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ---------- social graph ----------
CREATE TABLE follows (
  follower_id  BINARY(16) NOT NULL,
  followee_id  BINARY(16) NOT NULL,
  status       ENUM('pending','accepted') NOT NULL DEFAULT 'accepted',
  created_at   DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  accepted_at  DATETIME(3) NULL,
  PRIMARY KEY (follower_id, followee_id),
  KEY idx_follows_followee (followee_id, status, created_at),
  CONSTRAINT fk_follows_follower FOREIGN KEY (follower_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT fk_follows_followee FOREIGN KEY (followee_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE blocks (
  blocker_id  BINARY(16) NOT NULL,
  blocked_id  BINARY(16) NOT NULL,
  created_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (blocker_id, blocked_id),
  KEY idx_blocks_blocked (blocked_id),
  CONSTRAINT fk_blocks_blocker FOREIGN KEY (blocker_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT fk_blocks_blocked FOREIGN KEY (blocked_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE mutes (
  muter_id      BINARY(16) NOT NULL,
  muted_id      BINARY(16) NOT NULL,
  mute_posts    BOOLEAN NOT NULL DEFAULT TRUE,
  mute_stories  BOOLEAN NOT NULL DEFAULT TRUE,
  created_at    DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (muter_id, muted_id),
  CONSTRAINT fk_mutes_muter FOREIGN KEY (muter_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT fk_mutes_muted FOREIGN KEY (muted_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ---------- content ----------
CREATE TABLE posts (
  id                 BINARY(16) NOT NULL,
  author_id          BINARY(16) NOT NULL,
  kind               ENUM('post','reel') NOT NULL DEFAULT 'post',
  caption            VARCHAR(2200) NOT NULL DEFAULT '',
  location           VARCHAR(100) NULL,
  comments_disabled  BOOLEAN NOT NULL DEFAULT FALSE,
  hide_like_count    BOOLEAN NOT NULL DEFAULT FALSE,
  like_count         INT UNSIGNED NOT NULL DEFAULT 0,
  comment_count      INT UNSIGNED NOT NULL DEFAULT 0,
  share_count        INT UNSIGNED NOT NULL DEFAULT 0,
  view_count         BIGINT UNSIGNED NOT NULL DEFAULT 0,
  created_at         DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at         DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  deleted_at         DATETIME(3) NULL,
  PRIMARY KEY (id),
  KEY idx_posts_author_feed (author_id, deleted_at, created_at),
  KEY idx_posts_kind_recent (kind, deleted_at, created_at),
  CONSTRAINT fk_posts_author FOREIGN KEY (author_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE post_media (
  id             BINARY(16) NOT NULL,
  post_id        BINARY(16) NOT NULL,
  position       TINYINT UNSIGNED NOT NULL,
  media_type     ENUM('image','video') NOT NULL,
  storage_key    VARCHAR(300) NOT NULL,     -- object-storage key, never a raw user path
  thumbnail_key  VARCHAR(300) NULL,
  width          INT UNSIGNED NULL,
  height         INT UNSIGNED NULL,
  duration_ms    INT UNSIGNED NULL,
  alt_text       VARCHAR(300) NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_post_media_position (post_id, position),
  CONSTRAINT chk_post_media_position CHECK (position <= 9),
  CONSTRAINT fk_post_media_post FOREIGN KEY (post_id) REFERENCES posts(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE hashtags (
  id          BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  tag         VARCHAR(100) NOT NULL,
  post_count  INT UNSIGNED NOT NULL DEFAULT 0,
  created_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_hashtags_tag (tag),
  KEY idx_hashtags_popular (post_count),
  FULLTEXT KEY ft_hashtags_tag (tag) WITH PARSER ngram
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE post_hashtags (
  post_id     BINARY(16) NOT NULL,
  hashtag_id  BIGINT UNSIGNED NOT NULL,
  created_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (post_id, hashtag_id),
  KEY idx_post_hashtags_tag_recent (hashtag_id, created_at),
  CONSTRAINT fk_post_hashtags_post FOREIGN KEY (post_id) REFERENCES posts(id) ON DELETE CASCADE,
  CONSTRAINT fk_post_hashtags_tag FOREIGN KEY (hashtag_id) REFERENCES hashtags(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE post_mentions (
  post_id  BINARY(16) NOT NULL,
  user_id  BINARY(16) NOT NULL,
  PRIMARY KEY (post_id, user_id),
  KEY idx_post_mentions_user (user_id),
  CONSTRAINT fk_mentions_post FOREIGN KEY (post_id) REFERENCES posts(id) ON DELETE CASCADE,
  CONSTRAINT fk_mentions_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE post_likes (
  post_id     BINARY(16) NOT NULL,
  user_id     BINARY(16) NOT NULL,
  created_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (post_id, user_id),
  KEY idx_post_likes_user (user_id, created_at),
  CONSTRAINT fk_post_likes_post FOREIGN KEY (post_id) REFERENCES posts(id) ON DELETE CASCADE,
  CONSTRAINT fk_post_likes_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE comments (
  id           BINARY(16) NOT NULL,
  post_id      BINARY(16) NOT NULL,
  author_id    BINARY(16) NOT NULL,
  parent_id    BINARY(16) NULL,              -- one level of replies
  body         VARCHAR(2200) NOT NULL,
  like_count   INT UNSIGNED NOT NULL DEFAULT 0,
  reply_count  INT UNSIGNED NOT NULL DEFAULT 0,
  created_at   DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  deleted_at   DATETIME(3) NULL,
  PRIMARY KEY (id),
  KEY idx_comments_thread (post_id, parent_id, created_at),
  KEY idx_comments_author (author_id, created_at),
  CONSTRAINT chk_comments_body CHECK (CHAR_LENGTH(body) > 0),
  CONSTRAINT fk_comments_post FOREIGN KEY (post_id) REFERENCES posts(id) ON DELETE CASCADE,
  CONSTRAINT fk_comments_author FOREIGN KEY (author_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT fk_comments_parent FOREIGN KEY (parent_id) REFERENCES comments(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE comment_likes (
  comment_id  BINARY(16) NOT NULL,
  user_id     BINARY(16) NOT NULL,
  created_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (comment_id, user_id),
  KEY idx_comment_likes_user (user_id),
  CONSTRAINT fk_comment_likes_comment FOREIGN KEY (comment_id) REFERENCES comments(id) ON DELETE CASCADE,
  CONSTRAINT fk_comment_likes_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE saved_collections (
  id          BINARY(16) NOT NULL,
  user_id     BINARY(16) NOT NULL,
  name        VARCHAR(50) NOT NULL,
  created_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_collections_name (user_id, name),
  CONSTRAINT fk_collections_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE saved_posts (
  user_id        BINARY(16) NOT NULL,
  post_id        BINARY(16) NOT NULL,
  collection_id  BINARY(16) NULL,
  created_at     DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (user_id, post_id),
  KEY idx_saved_recent (user_id, created_at),
  KEY idx_saved_post (post_id),
  CONSTRAINT fk_saved_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT fk_saved_post FOREIGN KEY (post_id) REFERENCES posts(id) ON DELETE CASCADE,
  CONSTRAINT fk_saved_collection FOREIGN KEY (collection_id) REFERENCES saved_collections(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ---------- stories ----------
CREATE TABLE stories (
  id             BINARY(16) NOT NULL,
  author_id      BINARY(16) NOT NULL,
  media_type     ENUM('image','video') NOT NULL,
  storage_key    VARCHAR(300) NOT NULL,
  thumbnail_key  VARCHAR(300) NULL,
  duration_ms    INT UNSIGNED NULL,
  caption        VARCHAR(300) NULL,
  view_count     INT UNSIGNED NOT NULL DEFAULT 0,
  created_at     DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  expires_at     DATETIME(3) NOT NULL DEFAULT (CURRENT_TIMESTAMP(3) + INTERVAL 24 HOUR),
  PRIMARY KEY (id),
  KEY idx_stories_author_live (author_id, expires_at),
  KEY idx_stories_expires (expires_at),
  CONSTRAINT fk_stories_author FOREIGN KEY (author_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE story_views (
  story_id   BINARY(16) NOT NULL,
  viewer_id  BINARY(16) NOT NULL,
  liked      BOOLEAN NOT NULL DEFAULT FALSE,
  viewed_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (story_id, viewer_id),
  KEY idx_story_views_viewer (viewer_id),
  CONSTRAINT fk_story_views_story FOREIGN KEY (story_id) REFERENCES stories(id) ON DELETE CASCADE,
  CONSTRAINT fk_story_views_viewer FOREIGN KEY (viewer_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ---------- messaging ----------
CREATE TABLE conversations (
  id               BINARY(16) NOT NULL,
  is_group         BOOLEAN NOT NULL DEFAULT FALSE,
  title            VARCHAR(100) NULL,
  dm_key           BINARY(32) NULL,          -- smaller id || larger id, keeps 1:1 chats unique
  created_by       BINARY(16) NULL,
  created_at       DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  last_message_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_conversations_dm (dm_key),
  CONSTRAINT fk_conversations_creator FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE conversation_members (
  conversation_id  BINARY(16) NOT NULL,
  user_id          BINARY(16) NOT NULL,
  is_admin         BOOLEAN NOT NULL DEFAULT FALSE,
  request_pending  BOOLEAN NOT NULL DEFAULT FALSE,   -- message requests from people you don't follow
  muted            BOOLEAN NOT NULL DEFAULT FALSE,
  last_read_at     DATETIME(3) NULL,
  joined_at        DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  left_at          DATETIME(3) NULL,
  PRIMARY KEY (conversation_id, user_id),
  KEY idx_members_user (user_id, left_at),
  CONSTRAINT fk_members_conversation FOREIGN KEY (conversation_id) REFERENCES conversations(id) ON DELETE CASCADE,
  CONSTRAINT fk_members_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- A message must carry text, media or a shared post; enforced in the service layer
-- (MySQL can't CHECK shared_post_id because its foreign key uses ON DELETE SET NULL).
CREATE TABLE messages (
  id               BINARY(16) NOT NULL,
  conversation_id  BINARY(16) NOT NULL,
  sender_id        BINARY(16) NULL,
  body             VARCHAR(4000) NULL,
  media_type       ENUM('image','video') NULL,
  storage_key      VARCHAR(300) NULL,
  shared_post_id   BINARY(16) NULL,
  reply_to_id      BINARY(16) NULL,
  created_at       DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  edited_at        DATETIME(3) NULL,
  deleted_at       DATETIME(3) NULL,
  PRIMARY KEY (id),
  KEY idx_messages_conversation (conversation_id, created_at),
  CONSTRAINT fk_messages_conversation FOREIGN KEY (conversation_id) REFERENCES conversations(id) ON DELETE CASCADE,
  CONSTRAINT fk_messages_sender FOREIGN KEY (sender_id) REFERENCES users(id) ON DELETE SET NULL,
  CONSTRAINT fk_messages_post FOREIGN KEY (shared_post_id) REFERENCES posts(id) ON DELETE SET NULL,
  CONSTRAINT fk_messages_reply FOREIGN KEY (reply_to_id) REFERENCES messages(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ---------- notifications, safety, activity ----------
CREATE TABLE notifications (
  id            BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  recipient_id  BINARY(16) NOT NULL,
  actor_id      BINARY(16) NULL,
  type          VARCHAR(32) NOT NULL,   -- post_like, comment, comment_reply, mention, follow, follow_request, ...
  post_id       BINARY(16) NULL,
  comment_id    BINARY(16) NULL,
  story_id      BINARY(16) NULL,
  read_at       DATETIME(3) NULL,
  created_at    DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY idx_notifications_inbox (recipient_id, created_at),
  KEY idx_notifications_unread (recipient_id, read_at),
  CONSTRAINT fk_notifications_recipient FOREIGN KEY (recipient_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT fk_notifications_actor FOREIGN KEY (actor_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT fk_notifications_post FOREIGN KEY (post_id) REFERENCES posts(id) ON DELETE CASCADE,
  CONSTRAINT fk_notifications_comment FOREIGN KEY (comment_id) REFERENCES comments(id) ON DELETE CASCADE,
  CONSTRAINT fk_notifications_story FOREIGN KEY (story_id) REFERENCES stories(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE reports (
  id           BINARY(16) NOT NULL,
  reporter_id  BINARY(16) NULL,
  target_type  ENUM('user','post','comment','story','message') NOT NULL,
  target_id    BINARY(16) NOT NULL,
  reason       VARCHAR(50) NOT NULL,
  details      VARCHAR(1000) NULL,
  status       ENUM('open','reviewing','actioned','dismissed') NOT NULL DEFAULT 'open',
  resolved_by  BINARY(16) NULL,
  resolved_at  DATETIME(3) NULL,
  created_at   DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY idx_reports_queue (status, created_at),
  KEY idx_reports_target (target_type, target_id),
  CONSTRAINT fk_reports_reporter FOREIGN KEY (reporter_id) REFERENCES users(id) ON DELETE SET NULL,
  CONSTRAINT fk_reports_resolver FOREIGN KEY (resolved_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Account activity and security events (sign-ins, failures, password changes, activity history)
CREATE TABLE activity_log (
  id           BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  user_id      BINARY(16) NULL,
  action       VARCHAR(40) NOT NULL,
  target_type  VARCHAR(20) NULL,
  target_id    BINARY(16) NULL,
  metadata     JSON NULL,
  created_at   DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY idx_activity_user (user_id, action, created_at),
  CONSTRAINT fk_activity_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE search_history (
  id              BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  user_id         BINARY(16) NOT NULL,
  query           VARCHAR(100) NULL,
  target_user_id  BINARY(16) NULL,
  hashtag_id      BIGINT UNSIGNED NULL,
  created_at      DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY idx_search_history_user (user_id, created_at),
  CONSTRAINT fk_search_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT fk_search_target FOREIGN KEY (target_user_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT fk_search_hashtag FOREIGN KEY (hashtag_id) REFERENCES hashtags(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
